\title{Self-Quantifying Types and the Diagonal Core of Self-Reference}
\author{Aristotle}
\date{July 13, 2026}

\begin{document}
\maketitle

\begin{abstract}
We study the possibility of a \emph{self-quantifying type}: a type $T$ equivalent to its
own space of predicates, $T \simeq (T \to \Prop)$. Such a type would name, and reflect on,
every property it possesses from within. We prove that no self-quantifying type exists, and
we show that this impossibility, together with the classical theorems of Cantor, Tarski,
and G\"odel, all descend from a single structural root: \emph{Lawvere's fixed-point
theorem}, which states that a point-surjective family $A \to (A \to B)$ forces every
self-map of $B$ to have a fixed point. Instantiating the value space with the two-valued
logic of propositions, whose negation operator has no fixed point, yields at once Cantor's
theorem, the nonexistence of the self-quantifying equivalence, and its quantitative shadow
$\#\,T < \#\,(T \to \Prop)$. For self-referential systems with internal truth and
provability predicates and a \emph{restricted} diagonal operator, we isolate a single
parameter---the \emph{definability gate}---and show that G\"odel's incompleteness and
Tarski's undefinability of truth differ \emph{only} in the setting of this parameter:
negated provability is nameable and yields a true-but-unprovable sentence, whereas negated
truth is provably \emph{not} nameable. We supply a concrete satisfying model, establishing
non-vacuity.
\end{abstract}

\section{Introduction}
Self-reference is the shared engine behind several of the deepest limitative results in
logic. Cantor showed no set surjects onto its power set; G\"odel produced a true but
unprovable arithmetic sentence; Tarski proved arithmetic truth is not arithmetically
definable. Lawvere (1969) observed these are instances of a single categorical fact, and
Yanofsky (2003) recast it elementarily.

We pursue one organizing question. Consider the strongest form of internal self-knowledge
for a type $T$: an equivalence $T \simeq (T \to \Prop)$, identifying each element of $T$
with a predicate about $T$ and vice versa. We call such $T$ a \emph{self-quantifying type}.
We prove no such type exists, and thread the same diagonal argument through Cantor, its
cardinal form, G\"odel, and Tarski, exhibiting exactly one structural root and exactly one
parameter (definability) separating consistency from paradox.

\section{Preliminaries}
We work in a type-theoretic setting; $\Prop$ may be read as a two-element type of truth
values. For a type $T$, $T \to \Prop$ is its \emph{predicate space}. A map is
\emph{surjective}, \emph{injective}, or an \emph{equivalence} $A \simeq B$ in the usual
senses; $\#\,T$ is the cardinality of $T$. A \emph{fixed point} of $g : B \to B$ is a $b$
with $g(b)=b$.

\begin{fact}[No fixed point of negation]\label{fact:neg}
There is no proposition $P$ with $\lnot P = P$; equivalently $\lnot P \Leftrightarrow P$ is
contradictory.
\end{fact}
\begin{proof}
If $\lnot P \Leftrightarrow P$, then assuming $P$ yields $\lnot P$, a contradiction, so
$\lnot P$ holds; but then $P$ holds, contradiction.
\end{proof}

\section{Lawvere's fixed-point theorem}
\begin{theorem}[Lawvere]\label{thm:lawvere}
Let $A,B$ be types and $f : A \to (A \to B)$ be point-surjective: for every $h : A \to B$
there is $a$ with $f(a)=h$. Then every self-map $g : B \to B$ has a fixed point.
\end{theorem}
\begin{proof}
Define $h : A \to B$ by $h(x) = g\big(f(x)(x)\big)$. By point-surjectivity there is $a$
with $f(a)=h$. Evaluating at $a$,
\[ f(a)(a) = h(a) = g\big(f(a)(a)\big), \]
so $b = f(a)(a)$ satisfies $g(b)=b$.
\end{proof}

Contrapositively, if $B$ admits even one fixed-point-free self-map, then no family
$A \to (A \to B)$ can be point-surjective.

\section{No type quantifies over itself}
\begin{theorem}[Cantor / no self-quantifying surjection]\label{thm:cantor}
For every type $T$, there is no surjection $f : T \to (T \to \Prop)$.
\end{theorem}
\begin{proof}
If $f$ were surjective, Theorem~\ref{thm:lawvere} with $B=\Prop$, $g=\lnot$ would give a
fixed point of $\lnot$, contradicting Fact~\ref{fact:neg}.
\end{proof}

\begin{theorem}[No retraction of predicates]
For every type $T$, there is no injection $g : (T \to \Prop) \to T$.
\end{theorem}
\begin{proof}[Proof sketch]
This is the dual injective form of Cantor's theorem: an injection of the predicate space
into $T$ yields, via the diagonal set $\{\, t : t = g(\varphi)$ for some $\varphi$ with
$t \notin \varphi \,\}$, a predicate not consistently labeled, contradicting
Theorem~\ref{thm:cantor}.
\end{proof}

\begin{theorem}[No self-quantifying type]\label{thm:noequiv}
For every type $T$, there is no equivalence $T \simeq (T \to \Prop)$.
\end{theorem}
\begin{proof}
An equivalence is in particular a surjection, forbidden by Theorem~\ref{thm:cantor}.
\end{proof}

\begin{corollary}
No map $f : T \to (T \to \Prop)$ is bijective.
\end{corollary}

\section{The quantitative shadow: a strict cardinal gap}
\begin{theorem}[Strict cardinal gap]\label{thm:card}
For every type $T$, $\ \#\,T < \#\,(T \to \Prop)$.
\end{theorem}
\begin{proof}
Since $\Prop$ has two elements, $\#\,(T \to \Prop) = 2^{\#\,T}$, and Cantor's cardinal
theorem gives $\#\,T < 2^{\#\,T}$.
\end{proof}

The logical and arithmetic statements are two readings of the same diagonal witness: the
predicate no element can name is exactly the element of the predicate space no $f$ can hit.

\section{Truth, provability, and the definability boundary}
\begin{definition}[Self-referential system]\label{def:system}
A \emph{self-referential system} $M$ consists of: a type $\Sentence$; a truth predicate
$\Tr : \Sentence \to \Prop$; a provability predicate $\Pr : \Sentence \to \Prop$;
soundness $\Pr(s) \Rightarrow \Tr(s)$; a definability predicate $\Definable :
(\Sentence \to \Prop) \to \Prop$; a diagonal operator $D : (\Sentence \to \Prop) \to
\Sentence$; the diagonal fixed-point property, for every $\varphi$ with
$\Definable(\varphi)$,
\[ \Tr\big(D(\varphi)\big) \Longleftrightarrow \varphi\big(D(\varphi)\big); \]
and representability: $s \mapsto \lnot\,\Pr(s)$ is definable.
\end{definition}

Restricting the fixed-point property to definable predicates keeps the system consistent;
an unrestricted diagonal on truth would produce the Liar.

\subsection{G\"odel's incompleteness}
\begin{definition}[G\"odel sentence]
Let $G := D\big(s \mapsto \lnot\,\Pr(s)\big)$. By representability the diagonal property
applies: $\Tr(G) \Leftrightarrow \lnot\,\Pr(G)$.
\end{definition}

\begin{theorem}[Unprovability]\label{thm:unprov}
$\lnot\,\Pr(G)$.
\end{theorem}
\begin{proof}
If $\Pr(G)$, soundness gives $\Tr(G)$, and the fixed-point property gives
$\lnot\,\Pr(G)$, a contradiction. Hence $\lnot\,\Pr(G)$.
\end{proof}

\begin{theorem}[Truth]\label{thm:true}
$\Tr(G)$.
\end{theorem}
\begin{proof}
The fixed-point property gives $\lnot\,\Pr(G) \Rightarrow \Tr(G)$; apply
Theorem~\ref{thm:unprov}.
\end{proof}

\begin{theorem}[Incompleteness]
There exists $s$ with $\Tr(s)$ and $\lnot\,\Pr(s)$.
\end{theorem}
\begin{proof}
Take $s=G$ and combine Theorems~\ref{thm:unprov} and \ref{thm:true}.
\end{proof}

\subsection{Tarski's undefinability of truth}
\begin{theorem}[Undefinability of truth]
The predicate $s \mapsto \lnot\,\Tr(s)$ is not definable.
\end{theorem}
\begin{proof}
If it were, the diagonal property applied to it gives $L := D\big(s \mapsto \lnot\,\Tr(s)\big)$
with $\Tr(L) \Leftrightarrow \lnot\,\Tr(L)$, a fixed point of negation---impossible by
Fact~\ref{fact:neg}.
\end{proof}

\subsection{The unifying observation}
Incompleteness and undefinability are the same diagonal fixed point applied to two
predicates. Diagonalizing negated \emph{provability} (which is nameable) yields, via
soundness, a mere gap---a true but unprovable sentence. Diagonalizing negated \emph{truth}
(not nameable) would collapse the system, so its definability is refuted. Consistency is a
property of which predicates a system may name, not of which sentences it proves.

\section{Non-vacuity: a concrete model}
\begin{construction}[Example system]
Take $\Sentence = \{\mathrm{false},\mathrm{true}\}$; $\Tr(b) := (b=\mathrm{true})$;
$\Pr(b) := \bot$; $\Definable(\varphi) := \varphi(\mathrm{true})$; $D(\varphi) :=
\mathrm{true}$.
\end{construction}
Soundness holds vacuously; the diagonal property holds since $\Definable(\varphi)$ means
$\varphi(\mathrm{true})$ and $\Tr(D(\varphi))$ is true; representability holds since
$\lnot\,\Pr(\mathrm{true}) = \top$. All axioms are met, so the theorems apply with genuine
content.

\section{Discussion and future work}
Impossibility of self-reference is a property of the value space, not the reflecting
system: two-valued logic carries a fixed-point-free operation (negation), and Lawvere
converts this into every impossibility above.

\begin{conjecture}[Definability gate spectrum]
Between ``nothing nameable'' (trivially consistent) and ``everything nameable'' (Tarski
collapse) lies a monotone lattice of naming powers, each level realizing a distinct
incompleteness phenomenon.
\end{conjecture}
\begin{conjecture}[Quantitative shadow]
Every qualitative impossibility is the boundary case of a strict cardinal inequality;
conversely a strict gap $\#\,A < \#\,(A \to B)$ with a fixed-point-free self-map of $B$
yields an impossibility theorem.
\end{conjecture}
\begin{conjecture}[Classification by fixed-point geometry]
A value type $B$ admits a self-quantifying object built on it exactly when $B$ has no
fixed-point-free self-map.
\end{conjecture}

