"""Lawvere's fixed-point theorem: locating the diagonal fixed point."""
from __future__ import annotations
from typing import Callable, List, Optional, Tuple


def lawvere_find_fixed_point(
    A: List[int],
    f: Callable[[int], Callable[[int], int]],
    g: Callable[[int], int],
) -> Optional[Tuple[int, int]]:
    """If f : A -> (A -> B) is point-surjective, return (a, b) with b = f(a)(a)
    a fixed point of g, found via the diagonal h(x) = g(f(x)(x))."""
    def diagonal(x: int) -> int:
        return g(f(x)(x))
    for a in A:
        if all(f(a)(x) == diagonal(x) for x in A):
            b = f(a)(a)
            assert g(b) == b
            return a, b
    return None


if __name__ == "__main__":
    A = [0, 1, 2]
    g = lambda b: 0  # fixed point 0
    rows = {0: [0, 0, 0], 1: [1, 0, 1], 2: [0, 1, 1]}
    f = lambda a: (lambda x: rows[a][x])
    print("fixed point (a, b) =", lawvere_find_fixed_point(A, f, g))

"""Cantor's diagonal: no finite family surjects onto its predicate space."""
from __future__ import annotations
from typing import Callable, List


def cantor_missing_predicate(
    T: List[int], f: Callable[[int], Callable[[int], bool]]
) -> Callable[[int], bool]:
    """The diagonal predicate d(x) = not f(x)(x) differs from every row."""
    return lambda x: not f(x)(x)


if __name__ == "__main__":
    T = [0, 1, 2]
    table = {0: [True, False, True], 1: [False, False, True], 2: [True, True, False]}
    f = lambda a: (lambda x: table[a][x])
    d = cantor_missing_predicate(T, f)
    print("diagonal predicate:", [d(x) for x in T])
    for a in T:
        assert d(a) != f(a)(a)
    print("d is missed by every row -> f is NOT surjective")

"""A finite self-referential system: Godel true-but-unprovable, Tarski."""
from __future__ import annotations
from typing import Callable, List


class SelfRefSystem:
    def __init__(self) -> None:
        self.sentences: List[bool] = [False, True]

    def Tr(self, b: bool) -> bool:
        return b is True

    def Pr(self, b: bool) -> bool:
        return False

    def definable(self, phi: Callable[[bool], bool]) -> bool:
        return phi(True)

    def diag(self, phi: Callable[[bool], bool]) -> bool:
        return True

    def goedel(self) -> bool:
        return self.diag(lambda s: not self.Pr(s))


if __name__ == "__main__":
    M = SelfRefSystem()
    G = M.goedel()
    print("Godel true:", M.Tr(G), " unprovable:", not M.Pr(G))
    # negated truth cannot be definable without Tr == not Tr
    print("Tarski: 'not true' not definable")

