from typing import Callable, List


def cantor_diagonal(
    T: List[int], f: Callable[[int], Callable[[int], bool]]
) -> Callable[[int], bool]:
    """Build the predicate d(x) = not f(x)(x) that no row f(a) equals."""
    return lambda x: not f(x)(x)


def certify_not_surjective(
    T: List[int], f: Callable[[int], Callable[[int], bool]]
) -> bool:
    d = cantor_diagonal(T, f)
    return all(d(a) != f(a)(a) for a in T)

